// База знаний встроена при генерации файла (см. n8n/build_workflow.py).
// Поиск — упрощённый BM25 с отсечением русских окончаний, как в Python-боте.
const KB = [{"q": "Какие услуги оказывает автосервис?", "a": "Автосервис «Вектор» выполняет техническое обслуживание (ТО) легковых автомобилей и\nкроссоверов: замену масла и фильтров, диагностику, ремонт подвески и тормозной системы,\nшиномонтаж и сезонное хранение шин, развал-схождение, заправку кондиционера,\nкомпьютерную диагностику двигателя, ремонт электрики, замену ремня или цепи ГРМ.", "t": "услуги что делаете перечень работ чем занимаетесь"}, {"q": "Делаете ли вы кузовной ремонт и покраску?", "a": "Кузовной ремонт и покраску мы не выполняем. По кузову можем сделать только диагностику\nпосле ДТП и подсказать, что именно повреждено. Для покраски направим к партнёрам.", "t": "кузов покраска вмятина царапина ДТП"}, {"q": "Ремонтируете ли вы грузовые автомобили и микроавтобусы?", "a": "Нет, мы работаем только с легковыми автомобилями и кроссоверами массой до 3,5 тонн.\nГрузовые автомобили и автобусы не обслуживаем.", "t": "грузовик газель микроавтобус фура"}, {"q": "Обслуживаете ли вы электромобили и гибриды?", "a": "Гибриды обслуживаем по стандартным регламентам (масло, тормоза, подвеска, шины).\nВысоковольтную батарею и силовую электронику электромобилей не ремонтируем —\nтолько шиномонтаж, подвеску и тормоза.", "t": "электромобиль гибрид батарея Tesla Prius"}, {"q": "Делаете ли вы компьютерную диагностику?", "a": "Да. Компьютерная диагностика двигателя и электронных систем занимает около 30 минут.\nПо результатам распечатываем список ошибок и даём рекомендации. Если после диагностики\nвы заказываете ремонт у нас, стоимость диагностики вычитается из счёта.", "t": "диагностика check engine ошибка сканер чек"}, {"q": "Делаете ли вы шиномонтаж?", "a": "Да, шиномонтаж и балансировка колёс R13–R21. В сезон (апрель и октябрь–ноябрь) советуем\nзаписываться заранее. Есть сезонное хранение шин.", "t": "шины колёса переобуть балансировка резина"}, {"q": "Есть ли у вас сезонное хранение шин?", "a": "Да, принимаем комплекты шин на хранение на сезон (до 7 месяцев). Шины хранятся в сухом\nотапливаемом складе, каждый комплект маркируется. Стоимость уточняйте в разделе цен.", "t": "хранение шин склад сезон"}, {"q": "Заправляете ли вы кондиционер?", "a": "Да, заправка и диагностика кондиционера с проверкой на утечки. Используем хладагенты\nR134a и R1234yf. Процедура занимает около часа.", "t": "кондиционер фреон хладагент заправка"}, {"q": "Можно ли у вас пройти ТО по регламенту производителя с сохранением гарантии?", "a": "Да, мы выполняем ТО по регламенту производителя с использованием масел и запчастей,\nсоответствующих допускам. Все работы заносятся в сервисную книжку и в заказ-наряд.\nПо закону прохождение ТО в независимом сервисе не лишает гарантии дилера, если работы\nвыполнены по регламенту.", "t": "регламент гарантия дилера сервисная книжка плановое ТО"}, {"q": "Проводите ли вы предпродажную проверку автомобиля?", "a": "Да, проверка автомобиля перед покупкой: кузов толщиномером, подвеска, двигатель,\nкомпьютерная диагностика, проверка течей. Занимает около полутора часов. Вы получаете\nписьменный отчёт с фотографиями.", "t": "проверка перед покупкой подбор осмотр толщиномер"}, {"q": "Сколько стоит замена масла?", "a": "Замена моторного масла и масляного фильтра — 900 рублей за работу. Масло и фильтр\nоплачиваются отдельно: можно привезти свои или купить у нас. Для большинства\nлегковых автомобилей полная стоимость с материалами составляет 3 500–6 500 рублей.", "t": "масло цена масла стоимость замены масла фильтр"}, {"q": "Сколько стоит компьютерная диагностика?", "a": "Компьютерная диагностика — 1 200 рублей. При последующем ремонте у нас эта сумма\nвычитается из стоимости работ.", "t": "цена диагностики стоимость диагностики"}, {"q": "Сколько стоит шиномонтаж?", "a": "Переобувка четырёх колёс с балансировкой: R13–R15 — 2 000 рублей, R16–R17 — 2 400 рублей,\nR18–R19 — 2 800 рублей, R20–R21 — 3 400 рублей. Ремонт прокола — от 500 рублей.", "t": "цена шиномонтажа стоимость переобувки балансировка цена прокол"}, {"q": "Сколько стоит хранение шин?", "a": "Сезонное хранение комплекта из четырёх шин — 2 500 рублей за сезон (до 7 месяцев).\nКомплект на дисках — 3 000 рублей.", "t": "цена хранения шин"}, {"q": "Сколько стоит развал-схождение?", "a": "Развал-схождение на 3D-стенде — 2 500 рублей для легковых автомобилей и 3 000 рублей\nдля кроссоверов. Проверка без регулировки — 800 рублей.", "t": "сход-развал развал схождение цена развала"}, {"q": "Сколько стоит заправка кондиционера?", "a": "Заправка кондиционера с диагностикой утечек — 2 800 рублей (R134a) или 6 500 рублей\n(R1234yf). Антибактериальная обработка испарителя — 900 рублей.", "t": "цена заправки кондиционера стоимость фреона"}, {"q": "Сколько стоит замена тормозных колодок?", "a": "Замена передних тормозных колодок — 1 500 рублей за работу, задних — 1 500 рублей.\nЗамена колодок вместе с дисками — 2 500 рублей за ось. Запчасти оплачиваются отдельно.", "t": "колодки тормоза цена колодок тормозные диски"}, {"q": "Сколько стоит нормо-час?", "a": "Стоимость нормо-часа для слесарных работ — 1 800 рублей, для электрики и диагностики —\n2 000 рублей. Точную стоимость ремонта мастер называет после осмотра, и она фиксируется\nв заказ-наряде до начала работ.", "t": "нормочас нормо-час почём работа сколько стоит ремонт стоимость работ"}, {"q": "Можно ли оплатить картой или по безналу?", "a": "Принимаем наличные, банковские карты, оплату по СБП (по QR-коду) и безналичный расчёт\nс юридическими лицами по договору. Рассрочка не предоставляется.", "t": "оплата карта наличные безнал СБП юрлицо счёт"}, {"q": "Есть ли скидки или акции?", "a": "Постоянным клиентам после третьего визита — скидка 5 % на работы. При ТО вместе с\nшиномонтажом — балансировка в подарок. Актуальные акции публикуем в нашем\nTelegram-канале и на сайте.", "t": "скидка акция бонус программа лояльности"}, {"q": "Какой у вас режим работы?", "a": "Мы работаем ежедневно с 9:00 до 20:00 без обеда. Приём автомобилей заканчивается\nв 19:00. В праздничные дни режим может меняться — уточняйте у администратора.", "t": "часы работы график во сколько открываетесь до скольки работаете выходные"}, {"q": "Работаете ли вы по выходным?", "a": "Да, суббота и воскресенье — рабочие дни, с 9:00 до 20:00. Записи на выходные\nразбирают быстрее, лучше бронировать время за 2–3 дня.", "t": "суббота воскресенье выходные дни"}, {"q": "Где вы находитесь?", "a": "Автосервис «Вектор» находится в Омске по адресу: улица Тестовая, дом 1 (вымышленный\nадрес для демонстрации). Въезд на территорию со стороны улицы, есть бесплатная парковка\nдля клиентов на 10 мест.", "t": "адрес где находитесь как доехать местоположение карта"}, {"q": "Как к вам добраться на общественном транспорте?", "a": "Ближайшая остановка — «Тестовая улица» (вымышленная): автобусы 1 и 2, маршрутка 100.\nОт остановки до сервиса 3 минуты пешком.", "t": "остановка автобус транспорт пешком"}, {"q": "Как с вами связаться?", "a": "Телефон администратора: +7 (3812) 00-00-00 (вымышленный номер), электронная почта\ninfo@vektor-auto.example. Можно написать прямо сюда, в этот чат, — бот ответит на\nтиповые вопросы, а сложные передаст оператору.", "t": "телефон контакты почта email позвонить связаться"}, {"q": "Есть ли у вас зона ожидания?", "a": "Да, в сервисе есть зона ожидания с Wi-Fi, кофе и зарядками для телефона. Из зоны ожидания\nчерез стекло видно ремонтную зону. Небольшие работы (масло, шиномонтаж) можно подождать на\nместе.", "t": "ожидание подождать wi-fi кофе"}, {"q": "Есть ли подменный автомобиль или трансфер?", "a": "Подменный автомобиль не предоставляем. Если ремонт длится больше одного дня, администратор\nвызовет вам такси до дома за счёт сервиса (в пределах города).", "t": "подменный автомобиль такси трансфер как уехать"}, {"q": "Какая гарантия на работы?", "a": "Гарантия на все выполненные работы — 6 месяцев или 10 000 км пробега (что наступит раньше).\nГарантия подтверждается заказ-нарядом, поэтому сохраняйте его.", "t": "гарантия на ремонт срок гарантии гарантийный"}, {"q": "Какая гарантия на запчасти?", "a": "На запчасти, купленные у нас, действует гарантия производителя — обычно от 6 до 12 месяцев.\nНа запчасти, которые вы привезли сами, гарантия сервиса не распространяется — только на\nработу по их установке.", "t": "гарантия на запчасти свои запчасти запчасти клиента"}, {"q": "Что делать, если после ремонта появилась проблема?", "a": "Позвоните администратору или напишите в этот чат, опишите проблему и укажите номер\nзаказ-наряда. Мы запишем вас на бесплатный гарантийный осмотр в ближайший день. Если\nнеисправность связана с нашей работой, устраним за свой счёт.", "t": "проблема после ремонта жалоба рекламация претензия не помогло"}, {"q": "Можно ли установить запчасти, которые я привёз сам?", "a": "Да, устанавливаем запчасти клиента. В этом случае гарантия даётся только на работу,\nа не на деталь. Если деталь окажется бракованной, повторная установка оплачивается отдельно.", "t": "свои запчасти привезти детали установка своих деталей"}, {"q": "Вы выдаёте документы для отчётности?", "a": "Да, после ремонта выдаём заказ-наряд с перечнем работ и запчастей, кассовый чек, а по\nзапросу — акт выполненных работ. Для юридических лиц оформляем закрывающие документы по\nдоговору.", "t": "документы чек акт заказ-наряд отчётность"}, {"q": "Как записаться на обслуживание?", "a": "Записаться можно тремя способами: написать в этот чат (оператор подтвердит время),\nпозвонить администратору по телефону +7 (3812) 00-00-00 (вымышленный номер) или через\nформу на сайте. Для записи нужны марка и модель автомобиля, год выпуска, описание\nпроблемы и удобное время.", "t": "записаться запись забронировать время как попасть"}, {"q": "Можно ли приехать без записи?", "a": "Можно, но без гарантии, что примем сразу: в первую очередь обслуживаем клиентов по записи.\nНебольшие работы (ремонт прокола, замена лампы) обычно делаем в порядке живой очереди.", "t": "без записи живая очередь приехать сразу"}, {"q": "За сколько дней нужно записываться?", "a": "Обычно свободное время есть на ближайшие 1–2 дня. В сезон шиномонтажа (апрель,\nоктябрь–ноябрь) и перед праздниками лучше записываться за 3–5 дней.", "t": "сколько ждать когда свободно ближайшее время"}, {"q": "Как отменить или перенести запись?", "a": "Напишите в этот чат или позвоните администратору не позднее чем за 2 часа до записи —\nмы перенесём визит на удобное время. Штрафов за отмену нет.", "t": "отменить запись перенести не смогу приехать"}, {"q": "Сколько времени занимает ТО?", "a": "Стандартное ТО (масло, фильтры, осмотр) занимает 1–1,5 часа. Комплексное ТО с заменой\nтормозных колодок и жидкостей — 3–4 часа. Точное время мастер назовёт при приёме.", "t": "сколько длится ТО время ремонта долго ли"}, {"q": "Нужно ли присутствовать во время ремонта?", "a": "Нет, присутствовать не обязательно. Вы можете оставить автомобиль и уйти — мастер позвонит\nили напишет, когда работы будут закончены. По вашему желанию мастер покажет заменённые\nдетали.", "t": "присутствие оставить машину подождать"}, {"q": "Можно ли заказать запчасти через вас?", "a": "Да, подбираем и заказываем запчасти по VIN. Срок поставки оригинальных деталей — от 1 до\n7 дней, аналогов — обычно со склада в день обращения. Перед заказом согласовываем\nстоимость.", "t": "запчасти заказать детали VIN подбор запчастей"}];
const STOP = new Set(["а", "будет", "бы", "бывает", "был", "была", "было", "быть", "в", "вам", "вас", "ваш", "ваша", "ваше", "вашего", "вашей", "вашем", "вопрос", "вот", "вы", "где", "да", "день", "для", "до", "добрый", "его", "ее", "если", "есть", "еще", "ещё", "её", "же", "за", "здравствуйте", "и", "из", "или", "им", "интересует", "их", "к", "как", "какая", "какие", "каков", "какое", "какой", "когда", "кто", "ли", "меня", "мне", "можно", "мой", "мою", "моя", "мы", "на", "над", "надо", "нас", "наш", "не", "нет", "ну", "нужно", "о", "об", "он", "она", "они", "оно", "от", "очень", "по", "под", "подскажите", "пожалуйста", "при", "про", "с", "скажите", "так", "также", "там", "тоже", "тут", "у", "уже", "хотел", "хотела", "хотелось", "хочу", "чем", "что", "это", "я"]);
const SUFFIXES = ["иями", "ями", "ами", "ией", "иях", "иям", "ого", "его", "ому", "ему", "ыми", "ими", "ешь", "ишь", "ете", "ите", "ует", "уют", "ять", "ить", "ать", "еть", "уть", "ала", "ила", "ыла", "ось", "ась", "ия", "ию", "ии", "ие", "ые", "ое", "ее", "ая", "яя", "ую", "юю", "ой", "ый", "ий", "ов", "ев", "ей", "ам", "ям", "ах", "ях", "ом", "ем", "ат", "ят", "ет", "ут", "ют", "ит", "ло", "ла", "ли", "ть", "ся", "сь", "а", "я", "ы", "и", "е", "о", "у", "ю", "ь", "й"];
const REFLEXIVE = new Set(["ся", "сь"]);
const MIN_OVERLAP = 0.3; // доля слов вопроса, которые должны найтись в статье
const TOP_K = 3;

function stem(w) {
  for (let pass = 0; pass < 2; pass++) {
    let changed = false;
    for (const s of SUFFIXES) {
      if (!w.endsWith(s)) continue;
      const rest = w.length - s.length;
      const min = REFLEXIVE.has(s) ? 5 : (s.length === 1 ? 3 : 4);
      if (rest >= min) { w = w.slice(0, rest); changed = true; break; }
    }
    if (!changed) break;
  }
  return w;
}

function tokenize(text) {
  const words = text.toLowerCase().replace(/ё/g, "е").match(/[а-яa-z0-9]+/g) || [];
  return words.filter((w) => !STOP.has(w) && w.length > 1).map(stem);
}

const docs = KB.map((e) => [
  ...tokenize(e.q), ...tokenize(e.q), ...tokenize(e.t), ...tokenize(e.t), ...tokenize(e.a),
]);
const N = docs.length;
const avgdl = docs.reduce((s, d) => s + d.length, 0) / N;
const df = new Map();
for (const d of docs) for (const t of new Set(d)) df.set(t, (df.get(t) || 0) + 1);
const K1 = 1.5, B = 0.75;

function bm25(doc, query) {
  const tf = new Map();
  for (const t of doc) tf.set(t, (tf.get(t) || 0) + 1);
  let score = 0;
  for (const t of query) {
    const f = tf.get(t) || 0;
    if (!f) continue;
    const n = df.get(t) || 0;
    const idf = Math.log((N - n + 0.5) / (n + 0.5) + 1);
    score += (idf * f * (K1 + 1)) / (f + K1 * (1 - B + (B * doc.length) / avgdl));
  }
  return score;
}

const msg = $input.item.json.message || {};
const question = (msg.text || "").trim();
const query = tokenize(question);
const uniq = new Set(query);
const hits = docs
  .map((doc, i) => {
    const set = new Set(doc);
    const matched = [...uniq].filter((t) => set.has(t)).length;
    return { i, score: bm25(doc, query), overlap: uniq.size ? matched / uniq.size : 0 };
  })
  .filter((h) => h.score > 0 && h.overlap >= MIN_OVERLAP)
  .sort((a, b) => b.score - a.score)
  .slice(0, TOP_K);

const context = hits
  .map((h, n) => `[${n + 1}] Вопрос: ${KB[h.i].q}\nОтвет: ${KB[h.i].a}`)
  .join("\n---\n");

return {
  json: {
    chat_id: msg.chat ? msg.chat.id : null,
    user_name: msg.from ? [msg.from.first_name, msg.from.last_name].filter(Boolean).join(" ") : "",
    username: msg.from && msg.from.username ? "@" + msg.from.username : "",
    question,
    found: hits.length > 0,
    best_question: hits.length ? KB[hits[0].i].q : "",
    best_score: hits.length ? Math.round(hits[0].score * 100) / 100 : 0,
    context,
  },
};

parameters.inputSchema:
{
  "description": "Схема структурированного ответа модели.",
  "properties": {
    "covered": {
      "description": "true, если ответ на вопрос полностью следует из выдержек базы знаний; false, если выдержки не содержат ответа или вопрос не о компании",
      "title": "Covered",
      "type": "boolean"
    },
    "answer": {
      "description": "Ответ клиенту на русском языке (1–4 предложения). Пустая строка, если covered=false",
      "title": "Answer",
      "type": "string"
    }
  },
  "required": [
    "covered",
    "answer"
  ],
  "type": "object"
}

